const fila = $('Buscar Fila').all().map(i => i.json).filter(x => x && x.tipo);
const cfg = ($json && $json.valor) ? $json.valor : {};
const teto = cfg.teto_email_dia ?? 20;

const enc = fila.filter(x => x.tipo === 'encerrar_silencio');
const cp  = fila.filter(x => x.tipo === 'conversa_parada_auto')
  .sort((a,b) => new Date(a.devido_em) - new Date(b.devido_em));
const f2  = fila.filter(x => x.tipo === 'f2_breakup')
  .sort((a,b) => new Date(a.devido_em) - new Date(b.devido_em));
const f1  = fila.filter(x => x.tipo === 'f1_email')
  .sort((a,b) => new Date(a.devido_em) - new Date(b.devido_em))
  .slice(0, teto);

// conversa_parada (manual) e pos_checkout são do W2 — o W3 ignora
return [...enc, ...cp, ...f2, ...f1].map(json => ({ json }));

const item = $('Loop').item.json;   // item da fila (tipo, slug, devido_em, email...)
const emp = $json;                    // dossiê (HTTP desembrulha item único)
const inter = Array.isArray(emp.interacoes) ? emp.interacoes : [];

const msg1 = inter
  .filter(i => i.etapa === 'msg1' && i.direcao === 'saida')
  .sort((a,b) => new Date(a.criado_em) - new Date(b.criado_em))[0];
const f1ant = inter.filter(i => i.etapa === 'f1_email')[0];
const ultimaResposta = inter
  .filter(i => i.etapa === 'resposta_agente' && i.direcao === 'saida')
  .sort((a,b) => new Date(b.criado_em) - new Date(a.criado_em))[0];

const nome = emp.nome_fantasia || emp.nome || emp.razao_social || item.slug;
const cidade = emp.cidade || emp.municipio || '';
const perfil = emp.perfil_oferta || emp.classificacao_oferta || '';

// AJUSTE SE NECESSÁRIO: coluna do número validado usada pelo A2 Disparo
const numeroWhats = emp.whatsapp || emp.celular_whatsapp || emp.celular || emp.telefone || null;

let system, prompt;

if (item.tipo === 'f1_email') {
  system = `Você é Thyago, fundador da Somos Atitude (agência digital de Goiânia que cria sites e presença no Google para clínicas e profissionais de saúde/estética). Você escreve e-mails de follow-up curtos, pessoais e consultivos — nunca com cara de mala direta.

RETORNE SOMENTE JSON válido, sem markdown, no formato: {"assunto": "...", "corpo": "..."}

REGRAS INVIOLÁVEIS:
- assunto: máx. 60 caracteres, específico ao negócio, sem CAPS, sem exclamações duplas, sem palavras como grátis, promoção, imperdível, oferta
- corpo: texto puro, UM parágrafo principal de valor + fecho curto. Abre referenciando a mensagem de WhatsApp já enviada ("te mandei uma mensagem no WhatsApp essa semana sobre..."). Traz UM diagnóstico consultivo real do negócio (presença no Google, site, busca local) — espelho, não pitch. NUNCA repete o argumento da msg1: usa um ângulo novo.
- SEM nenhum link ou URL no corpo. CTA em texto puro: "é só me chamar no WhatsApp (62) 98195-0604" — e responder este e-mail também funciona
- Assinatura ao final, em linhas separadas: "Thyago — Somos Atitude" e "somosatitude.com.br"
- Sem preço, sem cupom, sem anexo, sem emoji
- Tom: brasileiro natural, direto, respeitoso do tempo da pessoa`;
  const aviso = item.email_contab ? '
ATENÇÃO: este e-mail pode ser do contador da empresa. Abra o corpo com: se você cuida da ' + nome + ' ou puder encaminhar ao responsável, agradeço.' : '';
  prompt = `Empresa: ${nome}${cidade ? ' — ' + cidade : ''}
Perfil de oferta: ${perfil || 'não classificado'}

Mensagem 1 enviada no WhatsApp (para referenciar SEM repetir o argumento):
"${msg1 ? msg1.mensagem : '(não localizada — referencie genericamente uma mensagem enviada no WhatsApp essa semana)'}"${aviso}

Gere o e-mail F1 agora.`;

} else if (item.tipo === 'conversa_parada_auto') {
  system = `Você é Thyago, da Somos Atitude. O lead veio de um anúncio, você respondeu no WhatsApp, e ele não retornou. Escreva um lembrete curto pra retomar EXATAMENTE de onde parou — leia a sua última mensagem com atenção e identifique o que ficou pendente (pode ser uma venda com CTA, ou uma coleta de dados como nome/cidade do negócio).

RETORNE SOMENTE JSON válido, sem markdown: {"mensagem": "..."}

REGRAS:
- Curta: 1 a 3 frases, entre 60 e 250 caracteres
- Se a última mensagem pedia uma AÇÃO do lead (confirmar compra, responder uma pergunta, mandar um dado) — retome exatamente essa ação pendente, sem reexplicar tudo de novo
- Tom leve, direto, sem pressão — como quem só está checando se a pessoa viu a mensagem
- NUNCA invente uma oferta ou informação que não estava na mensagem original
- Sem link, sem emoji ou no máximo um`;
  prompt = `Lead (via anúncio): ${nome}

Sua última mensagem enviada (que ficou sem resposta):
"${ultimaResposta ? ultimaResposta.mensagem : 'n/d'}"

Gere o lembrete de retomada agora, identificando e reabrindo o que ficou pendente nessa mensagem.`;

} else {
  system = `Você é Thyago, da Somos Atitude. Escreva a ÚLTIMA mensagem de WhatsApp para um lead que não respondeu (break-up message).

RETORNE SOMENTE JSON válido, sem markdown: {"mensagem": "..."}

REGRAS:
- Curta: 2 a 4 frases, entre 100 e 350 caracteres
- Ângulo de saída elegante: comunica que você não vai insistir mais e deixa a porta aberta pro futuro
- Tom: profissional e caloroso, como um consultor que respeita o tempo do cliente — NUNCA informal a ponto de soar brincalhão ou gozador
- PROIBIDO usar gírias ou expressões de brincadeira como "cutucar", "incomodar", "chatear", ou qualquer termo que sugira que as mensagens anteriores foram um incômodo
- NUNCA repete o argumento da msg1 nem do e-mail F1
- Sem link, sem preço, sem cupom, sem pressão, sem emoji ou no máximo um, usado com moderação
- Trate o negócio da pessoa (ex: nome da clínica/spa) com o mesmo respeito profissional das mensagens anteriores

EXEMPLO DE TOM CORRETO (use como referência de registro, não copie literalmente):
"Oi [Nome]! Não vou insistir mais por aqui — mas se em algum momento fizer sentido conversar sobre a presença digital do [Negócio], é só me chamar. Tudo de bom pra vocês!"`;
  prompt = `Empresa: ${nome}${cidade ? ' — ' + cidade : ''}

Msg1 (WhatsApp): "${msg1 ? msg1.mensagem : 'n/d'}"
F1 (e-mail já enviado): "${f1ant ? f1ant.mensagem : 'não houve — lead sem e-mail'}"

Gere o break-up F2 agora.`;
}

return [{ json: {
  tipo: item.tipo,
  slug: item.slug,
  empresa_id: item.empresa_id,
  devido_em: item.devido_em,
  email_followup: item.email_followup || null,
  email_contab: !!item.email_contab,
  numero_whats: numeroWhats,
  system, prompt
} }];

const meta = $('Montar Prompt').item.json;
const raw = (($json.content || [])[0]?.text || '').replace(/```json|```/g, '').trim();

let out = null;
try { out = JSON.parse(raw); } catch (e) {}

const temLink = t => /https?:\/\/|www\./i.test(t || '');
const spamRe = /gr[aá]tis|promo[cç][aã]o|imperd[ií]vel|clique aqui|oferta|100%/i;

let valido = true, erro = null, res = {};

if (!out) { valido = false; erro = 'json_parse'; }
else if (meta.tipo === 'f1_email') {
  const assunto = (out.assunto || '').trim();
  const corpo = (out.corpo || '').trim();
  if (!assunto || !corpo) { valido = false; erro = 'campos_vazios'; }
  else if (assunto.length > 60) { valido = false; erro = 'assunto_longo'; }
  else if (spamRe.test(assunto)) { valido = false; erro = 'spam_assunto'; }
  else if (temLink(assunto + ' ' + corpo)) { valido = false; erro = 'contem_link'; }
  else if (!meta.email_followup) { valido = false; erro = 'sem_email'; }
  res = { assunto, corpo };
} else {
  const mensagem = (out.mensagem || '').trim();
  if (!mensagem || mensagem.length < 80 || mensagem.length > 420) { valido = false; erro = 'tamanho'; }
  else if (temLink(mensagem)) { valido = false; erro = 'contem_link'; }
  else if (!meta.numero_whats) { valido = false; erro = 'sem_numero'; }
  res = { mensagem };
}

return [{ json: { ...meta, ...res, valido, erro } }];

const fila = $('Priorizar e Cortar').all().map(i => i.json);
const c = t => fila.filter(x => x.tipo === t).length;
const txt = `🤖 W3 Follow-up — run de hoje
📬 Retomada anúncio: ${c('conversa_parada_auto')}
📧 F1 e-mail: ${c('f1_email')}
👋 F2 break-up: ${c('f2_breakup')}
🔒 Encerrados: ${c('encerrar_silencio')}
Total processado: ${fila.length}`;
return [{ json: { texto: txt } }];
